mapper.select:
select id, type, title, author_name as author, thumbnail_url as thumbnail, video_url as videoUrl, duration_sec as duration, quality, views, tags, null as description from recite_video
where type = #{type}
order by views desc, id desc limit 12

mapper.delete:
delete from recite_favorite
where user_id = #{userId}
  and target_id = #{targetId}
  and favorite_type = #{favoriteType}

mapper.select:
select count(1)
from recite_favorite
where user_id = #{userId}
  and target_id = #{targetId}
  and favorite_type = #{favoriteType}

SELECT id, poem_id as poemId, title, poet_name as poetName, dynasty, content, difficulty_level as difficultyLevel, recommended_duration as recommendedDuration, emotion_type as emotionType, is_featured as isFeatured FROM recite_poem_selection WHERE 1=1
AND difficulty_level = #{difficultyLevel}
AND emotion_type = #{emotionType}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR poet_name LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY is_featured DESC, sort_order ASC, id ASC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1) FROM recite_poem_selection WHERE 1=1
AND difficulty_level = #{difficultyLevel}
AND emotion_type = #{emotionType}
AND (title LIKE CONCAT('%', #{keyword}, '%') OR poet_name LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))
